"""Folders of a workspace output tree that keep the documents generated by each module.

Every generated document lives below ``output/reports/<module>/``. Workspaces,
backups and transfer packages written with the former layout (module folders
directly below ``output/`` and loose documents in ``output/reports/``) are moved
to these folders once, and the paths stored in the workspace database follow them.
"""
from __future__ import annotations

import re
import shutil
import sqlite3
from contextlib import closing
from pathlib import Path

REPORTS_FOLDER = 'reports'
DESIGNS_FOLDER = 'ppt-designs'
CDR_ANALYSIS_FOLDER = 'cdr-analysis'
NETWORK_INSIGHTS_FOLDER = 'network-insights'
# The folders of the PowerPoint reports and Chart Sets of PPT Reporting (old), a module the tool no longer has: no module
# writes to them any more, but the documents they keep stay there, and those of the former layouts still move into them.
REPORTS_OLD_FOLDER = 'reports-old'
REPORTS_CHARTS_OLD_FOLDER = 'reports-charts-old'
REPORTING_JOBS_FOLDER = 'reporting-jobs'
BUNDLE_REPORTS_FOLDER = 'bundle-reports'
MODULE_FOLDERS = frozenset({
    DESIGNS_FOLDER, CDR_ANALYSIS_FOLDER, NETWORK_INSIGHTS_FOLDER,
    REPORTS_OLD_FOLDER, REPORTS_CHARTS_OLD_FOLDER, REPORTING_JOBS_FOLDER, BUNDLE_REPORTS_FOLDER,
})
# Former folders directly below output/ (and those of the Bundle Report Templates when they were called Complete
# Reports or Reporting Jobs Templates, and of PPT Designer when it was PPT Dashboards) and the module folder that
# replaces each one.
LEGACY_OUTPUT_FOLDERS = (
    ('dashboards', DESIGNS_FOLDER),
    (f'{REPORTS_FOLDER}/dashboards', DESIGNS_FOLDER),
    (f'{REPORTS_FOLDER}/designs', DESIGNS_FOLDER),
    ('reporting', REPORTING_JOBS_FOLDER),
    ('charts', REPORTS_CHARTS_OLD_FOLDER),
    ('report-charts', REPORTS_CHARTS_OLD_FOLDER),
    (f'{REPORTS_FOLDER}/complete-reports', BUNDLE_REPORTS_FOLDER),
    (f'{REPORTS_FOLDER}/reporting-jobs-templates', BUNDLE_REPORTS_FOLDER),
)
# The charts of a PPT job of PPT Designer, in its folder, as PPT Dashboards named them.
LEGACY_CHARTS_FOLDER, CHARTS_FOLDER = 'dashboard-charts', 'design-charts'
STORED_PATH_COLUMNS = (
    ('design_ppt_jobs', 'output_path'),
    ('report_task_runs', 'output_dir'),
)
NETWORK_INSIGHTS_FILE = re.compile(r'_summary_network_insights\.(?:pptx|docx)$')
CDR_ANALYSIS_FILE = re.compile(r'(?:_summary_dataset_analysis|_report(?:_[0-9a-f]{10})?)\.(?:pptx|docx)$')


def reports_root(output_dir: Path | str) -> Path:
    return Path(output_dir) / REPORTS_FOLDER


def module_output_dir(output_dir: Path | str, folder: str, *, create: bool = False) -> Path:
    """Return ``output/reports/<folder>`` of a workspace output tree."""
    directory = reports_root(output_dir) / folder
    if create:
        directory.mkdir(parents=True, exist_ok=True)
    return directory


def _loose_report_folder(item: Path) -> str:
    """Module folder of an entry left directly in output/reports by an earlier version."""
    if item.is_dir():
        return REPORTS_OLD_FOLDER
    if NETWORK_INSIGHTS_FILE.search(item.name):
        return NETWORK_INSIGHTS_FOLDER
    if CDR_ANALYSIS_FILE.search(item.name):
        return CDR_ANALYSIS_FOLDER
    return REPORTS_OLD_FOLDER


def _merge_into(source: Path, destination: Path, moves: list[tuple[Path, Path]]) -> None:
    """Move ``source`` to ``destination``, merging folders and never overwriting existing entries."""
    if not source.exists() or source == destination:
        return
    if not destination.exists():
        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.move(str(source), str(destination))
        moves.append((source, destination))
        return
    if source.is_dir() and destination.is_dir():
        for child in list(source.iterdir()):
            _merge_into(child, destination / child.name, moves)
        try:
            source.rmdir()
        except OSError:
            pass


def _rewrite_stored_paths(database_path: Path, moves: list[tuple[Path, Path]]) -> None:
    if not Path(database_path).is_file():
        return
    prefixes = sorted(((str(old), str(new)) for old, new in moves), key=lambda item: len(item[0]), reverse=True)
    with closing(sqlite3.connect(database_path, timeout=60)) as connection, connection:
        tables = {str(row[0]) for row in connection.execute("SELECT name FROM sqlite_master WHERE type = 'table'")}
        for table, column in STORED_PATH_COLUMNS:
            if table not in tables:
                continue
            for row_id, value in connection.execute(f'SELECT rowid, {column} FROM {table}').fetchall():
                text = str(value or '')
                for old, new in prefixes:
                    if text == old or text.startswith(old + '/'):
                        connection.execute(f'UPDATE {table} SET {column} = ? WHERE rowid = ?', (new + text[len(old):], row_id))
                        break


def migrate_output_layout(output_dir: Path | str, database_path: Path | str) -> bool:
    """Move documents written with the former output layout into their module folders.

    Returns whether anything was moved. Safe to call on every workspace activation.
    """
    output_dir = Path(output_dir)
    root = reports_root(output_dir)
    moves: list[tuple[Path, Path]] = []
    for legacy, folder in LEGACY_OUTPUT_FOLDERS:
        _merge_into(output_dir / legacy, root / folder, moves)
    designs = root / DESIGNS_FOLDER
    if designs.is_dir():
        for job in list(designs.iterdir()):
            if (job / LEGACY_CHARTS_FOLDER).is_dir():
                _merge_into(job / LEGACY_CHARTS_FOLDER, job / CHARTS_FOLDER, moves)
    if root.is_dir():
        for item in list(root.iterdir()):
            if item.name in MODULE_FOLDERS or item.name.startswith('.'):
                continue
            _merge_into(item, root / _loose_report_folder(item) / item.name, moves)
    if moves:
        _rewrite_stored_paths(Path(database_path), moves)
    return bool(moves)
